/* giant clams */
const CLAMS=[{x:1.2,z:-2.6},{x:-4.5,z:2.2},{x:6.2,z:1.0},{x:-2.0,z:-5.5},{x:3.6,z:5.2},{x:-6.4,z:-2.8}];
const CLAM_PAL=[[0.1,0.45,1.0],[0.08,0.8,0.75],[0.3,0.85,0.25],[0.55,0.25,0.9],[0.15,0.6,1.0],[0.75,0.6,0.2]];
