function onChimney(c,u,a,out){const y=u*c.h,r=chimR(c,y)*(1+0.12*Math.sin(a*3+y*1.7+c.seed));out.pos.set(c.x+Math.cos(a)*r,c.y0+y,c.z+Math.sin(a)*r);out.n.set(Math.cos(a),0.35,Math.sin(a)).normalize();return out;}
