  for(const k in JELLY){const J=JELLY[k];if(J.active){for(let i=0;i<J.n;i++)J.p[i*3+1]+=dy;J.resetT=true;}}
  bubbles.forEach(b=>b.on=false);sparkAge.fill(99);
